/**
 * Canonical credential fence shared by in-house file-reading DSH plugins.
 *
 * The host filesystem sandbox gates writes by session mode, so this module adds
 * an independent lexical fence over resolved paths: plugins never read or
 * traverse credential material even in danger-full-access, and refusals never
 * echo the denied path back to the model.
 *
 * THIS FILE IS THE SOURCE OF TRUTH. Copies in plugins are generated by
 * `tools/sync-shared-code.mjs` and must stay byte-identical.
 *
 * ASCII only: see the workspace AGENTS.md encoding rule.
 */

import { basename } from 'node:path'

/** Directory names that hold key material or cloud credentials. */
export const DENY_DIRS = new Set([
  '.ssh',
  '.aws',
  '.gnupg',
  '.kube',
  '.docker',
  '.password-store',
])

/** Exact file names that are credential stores. */
export const DENY_FILES = new Set([
  '.netrc',
  '_netrc',
  '.npmrc',
  '.pypirc',
  '.git-credentials',
  '.gitconfig',
  'credentials',
  'credentials.json',
  'credentials.yaml',
  'credentials.yml',
  'secrets.json',
  'secrets.yaml',
  'secrets.yml',
  'id_rsa',
  'id_dsa',
  'id_ecdsa',
  'id_ed25519',
  '.env',
])

/** Suffix patterns for private key / keystore files. */
export const DENY_SUFFIXES = ['.pem', '.key', '.p12', '.pfx', '.keystore', '.jks']

/**
 * Whether a resolved absolute path (file or directory) is credential material.
 * @param {string} absPath - backend-resolved display path.
 * @returns {boolean} true when the path must be refused.
 */
export function isCredentialPath(absPath) {
  const raw = String(absPath)
  const parts = raw.split(/[\\/]+/).filter((part) => part.length > 0)
  for (const part of parts) {
    if (DENY_DIRS.has(part.toLowerCase())) return true
  }
  const name = basename(raw).toLowerCase()
  if (DENY_FILES.has(name)) return true
  if (name.startsWith('.env.') || name.endsWith('.env')) return true
  for (const suffix of DENY_SUFFIXES) {
    if (name.endsWith(suffix)) return true
  }
  // Generic `*credential*` / `*secret*` stores, but not ordinary prose files.
  if (/credential|secret/i.test(name) && /\.(json|ya?ml|ini|conf|txt|env)$/i.test(name)) return true
  return false
}

/**
 * A model-facing refusal that deliberately omits the denied path.
 * @param {string} [pluginName='filekit'] - plugin identifier for diagnostics.
 * @returns {Error}
 */
export function credentialDenied(pluginName = 'filekit') {
  const error = new Error(
    `${pluginName}: that path is credential material and is refused by policy `
      + '(credential files and key directories are never read by this plugin, in any sandbox mode). '
      + 'Use the host read tool instead if the operator explicitly wants it opened.',
  )
  error.code = 'CREDENTIAL_DENIED'
  return error
}
